(function(root){'use strict';
const t=en=>({en}),VERSION='ac01-projects-1';
const text=(id,en)=>({id,label:t(en),type:'text'});
const choose=(id,en,options)=>({id,label:t(en),type:'select',options});
const option=(value,en)=>({value,label:t(en)});
const reason=text('reason','Explain the comparisons or evidence behind your answer. Uncertainty is welcome.');
const prediction=()=>[choose('choice','Your first choice',[option('first','First option'),option('second','Second option'),option('other','Another plan / unsure')]),reason];
const strategies=(labels)=>[
 ...['A0','A1','B0','B1'].map((id,i)=>choose(id,(i<2?'A':'B')+': best response when the other chooses '+labels[i%2].en,[option('0',labels[0].en),option('1',labels[1].en),option('both','Both tie')])),
 choose('dominance','Which option is strictly dominant for both players?',[option('0',labels[0].en),option('1',labels[1].en),option('none','Neither')]),
 {id:'ne',type:'ne',label:t('Select ALL pure Nash equilibria, or select “none”. A tie is not a profitable deviation.')},reason];
const NS=[t('N · North entrance'),t('S · Sports field')],CD=[t('C · Complete'),t('D · Skip')];
const matrixStep=(id,title,body,model)=>({id,title,body,model,matrix:true,fields:[text('calculation','Show at least one payoff calculation.')],hint:t('Separate the shared benefit or demand from each player’s own costs. Every cell records A first, then B.')});
const analyze=(id,title,body,model,labels)=>({id,title,body,model,fields:strategies(labels),hint:t('Hold the other player’s choice fixed. Compare only your own payoff. Repeat for both players and every proposed equilibrium.')});
const ACTIVITIES=[{
 id:'food-trucks',title:t('Food trucks at the school fair'),kind:t('Project · 25–35 minutes'),intro:t('Where should you park when another truck is choosing too? Build a model, test a change in demand, and advise the organizer.'),labels:NS,
 story:t('Two food trucks, A and B, simultaneously choose N (north entrance) or S (sports field). North has 120 customers; south has 80. Each buys one meal. A truck alone serves everyone in its area; two trucks in one area split customers equally. Capacity is sufficient, trucks are equally appealing, and customers do not move between areas. Demand in an empty area is lost. Each meal contributes USD 5 after variable costs. Each truck then pays its own fixed USD 100 cost once. Profit = meals × USD 5 − USD 100. These are simplified assumptions, not observed school data.'),
 steps:[
 {id:'predict',title:t('01 · Choose before calculating'),body:t('First option: N. Second option: S. Where would you choose? What do you expect B to do, and why?'),fields:prediction()},
 matrixStep('baseline',t('02 · Build the payoff table'),t('Calculate all eight profits in USD. Remember to split demand when both trucks choose the same area.'),'trucks80'),
 analyze('strategy',t('03 · Can one truck improve alone?'),t('Use the original demand: north 120, south 80. Explain why staying or switching is a best response, and check every equilibrium. Maximizing total profit is a different question.'),'trucks80',NS),
 {...matrixStep('change',t('04 · South demand falls to 50'),t('Only south demand changes, from 80 to 50. Recalculate. Does either truck now have a strictly dominant choice? Find all equilibria and explain a unilateral deviation from a split location.'),'trucks50'),fields:[...strategies(NS)]},
 {id:'recommend',title:t('05 · Two different recommendations'),body:t('Advise truck A and the organizer separately. State your assumptions, information to collect, and what would make you reconsider. With south demand 50, compare total truck profit at NN and split locations. That total does not measure customers’ welfare. An allocation rule changes the game; saying “cooperate” does not enforce it.'),fields:[text('truck','Recommendation to A: I recommend… because… assuming… I would reconsider if…'),text('organizer','Recommendation to the organizer, including implementation and missing information')]},
 {...analyze('boundary',t('06 · Optional boundary: south has 60'),t('Find all equilibria when south demand is exactly 60. Explain the difference between weak and strict dominance. You may leave this extension unfinished.'),'trucks60',NS),optional:true}
 ]
},{
 id:'shared-printer',title:t('Who maintains the shared printer?'),kind:t('Project · 30–40 minutes'),intro:t('Two clubs share a 3D printer. Compare a deduction with a practical way to reduce maintenance costs.'),labels:CD,
 story:t('Robotics club A and design club B each have a different maintenance checklist. They simultaneously choose Complete (C) or Skip (D). If both complete, each receives benefit 10; if only one completes, each receives 6; if neither completes, each receives 3. Completing costs that club 5; skipping costs 0. Payoff = benefit − own cost. These are invented utility points, not money, grades, or measured happiness. Higher points are preferred.'),
 steps:[
 {id:'predict',title:t('01 · What would your club do?'),body:t('First option: complete. Second option: skip. Predict your choice and the other club’s choice before seeing a solution.'),fields:prediction()},
 matrixStep('baseline',t('02 · Benefit minus own cost'),t('Calculate each payoff. When neither club completes, each still receives benefit 3.'),'printer0'),
 analyze('strategy',t('03 · A shared difficulty'),t('Compare best responses and all equilibria. Explain how both can prefer CC while each has an incentive to skip.'),'printer0',CD),
 {...matrixStep('fee15',t('04 · A deduction of 1.5 points'),t('Every club that skips certainly loses f = 1.5 additional points. The deduction is not transferred to the other club. All benefits and costs stay the same. Recalculate and find ALL equilibria.'),'printer15'),fields:strategies(CD)},
 {...matrixStep('fee3',t('05 · A deduction of 3 points'),t('Now the certainly enforced deduction is f = 3. Recalculate and compare with f = 0 and f = 1.5. Does every positive deduction guarantee cooperation?'),'printer3'),fields:strategies(CD)},
 {...matrixStep('training',t('06 · An alternative: easier maintenance'),t('Remove all deductions. Suppose training and tools reduce each checklist’s cost from 5 to 2 without changing benefits. Find the new payoffs and equilibria. This cost reduction is an assumption to investigate, not a proven result.'),'printerTraining'),fields:strategies(CD)},
 {id:'proposal',title:t('07 · Recommend a workable rule'),body:t('Compare no rule, deductions, and training. Account for monitoring, enforcement, fairness, upfront training cost and whether the assumed cost reduction is realistic. Explain what evidence could change your proposal. Repeated contact alone does not guarantee cooperation.'),fields:[text('proposal','Proposal, supporting payoff comparisons, implementation and limitations')]},
 {id:'boundary',title:t('08 · Optional: uncertain enforcement'),body:t('For any f ≥ 0, when is CC an equilibrium? When is DD? Check the ties at f = 1 and f = 2. Next suppose a 3-point deduction detects skipping with probability q = 0.5, never punishes completion, and clubs maximize expected points. Compare with certain f = 1.5. What q makes C strictly dominant?'),fields:[reason],optional:true,
 solution:t('CC is an equilibrium iff f ≥ 1; DD iff f ≤ 2. Both exist for 1 ≤ f ≤ 2. C is strictly dominant only when f > 2. Under the stated expected-points assumptions the effective deduction is 3q: at q = 0.5 both CC and DD remain equilibria; strict dominance needs q > 2/3. At q = 2/3 there is a tie and both remain. Expected points are an expected value: each possible number of points times its probability, added up. The Probability course develops expected value.')}
 ]
},{
 id:'missed-deadline',title:t('When a teammate misses a deadline'),kind:t('Case study · 20–30 minutes'),intro:t('Separate facts from assumptions, respond to new evidence, and write a conditional plan with credible limits.'),
 story:t('Wednesday, 18:00. Your group’s data poster is due Friday at 15:00. You handle data, Kai makes graphs, and Mina handles layout and presentation. There is a shared project grade and no clear individual contribution policy. Kai promised a first graph by Wednesday 17:00. No file has arrived. At 16:30 Kai wrote, “I’ll work on it later.” You do not know why. You and Mina still have your own work to finish. This is a fictional case; do not enter real classmates’ private details.'),
 steps:[
 {id:'initial',title:t('01 · Your decision with limited information'),body:t('You may combine actions: do some of Kai’s work, agree on a verifiable checkpoint, redistribute tasks, or ask the teacher for help. What would you do now, and why? Save this initial decision before reading new information.'),fields:[text('plan','Initial action and reasons')]},
 {id:'evidence',title:t('02 · What do you actually know?'),body:t('Distinguish evidence from motive. If Kai expects you to finish everything, how might that affect incentives? Treat this as a hypothesis, not a fact. A request to the teacher is allowed; you cannot unilaterally change grades or remove a teammate.'),fields:[text('facts','List three known facts and two assumptions separately'),text('alternatives','Give two possible explanations and information that would distinguish them'),text('message','Draft a message asking about progress, obstacles and a small deliverable with a deadline'),text('limits','How much help, until when, and what fallback? Explain the possible incentive effect.')]},
 {id:'branchA',title:t('03 · Branch A: a skill obstacle'),body:t('Independent branch A: Kai has cleaned the data but does not know which graph would compare it or how to label axes. Kai has one hour available Thursday. Keep or revise your initial plan. Consider a brief demonstration, a small sketch, or repartitioning. What independently completed next step would you verify?'),fields:[text('revision','What stays, what changes, and which new evidence explains your decision?'),text('checkpoint','Concrete task, check time, evidence of progress and fallback')]},
 {id:'transfer',title:t('04 · Transfer: choose a different branch'),body:t('B and C are independent alternatives to A, not later events in the same story. Choose at least one. You can submit one, switch branches, and submit the other; both versions remain in your history.'),fields:[choose('branch','Independent branch',[option('B','B · Skill and time are available'),option('C','C · Still unreachable Thursday')]),text('revision','Keep or revise your plan: cite the new evidence, action, checkpoint and fallback')],branches:{B:t('Kai can do the task and has time, but says other work takes priority because Kai expects you to finish this project. Set responsibilities, bounded help and credible checkpoints; do not invent authority you do not have.'),C:t('It is now Thursday 16:00. Kai remains unreachable and there is no file; the reason is still unknown. Plan a minimum viable submission, record observable facts, set a stopping point, and ask the teacher for support if needed.')}},
 {id:'final',title:t('05 · A conditional action plan'),body:t('Write at least two usable “if… then…” rows. Each should name a condition, action, observable output, check time and fallback. Review assumptions, strategic reasoning, use of evidence, and feasibility. These dimensions support self or teacher review; no essay score or personality label is generated.'),fields:[text('row1','Plan row 1: condition → action → output → check time → fallback'),text('row2','Plan row 2: condition → action → output → check time → fallback'),text('review','Self-review: which parts have clear support, partial support or need more detail? What would you ask a teacher to review?')],solution:t('One possible response asks about the obstacle, agrees on a small graph with axes and units by Thursday noon, limits help, and names a fallback. Branch A can justify a brief demonstration; B can justify firmer verifiable responsibilities; C can justify a smaller submission and a factual request for teacher support. Other plans can be defensible. Explain evidence, constraints and tradeoffs; do not infer laziness from a missing file.')}
 ]
}];
const api={VERSION,ACTIVITIES};if(typeof module==='object'&&module.exports)module.exports=api;else root.QuidenceGameProjectsContent=api;
})(typeof window==='undefined'?globalThis:window);
